package com.jadhavr.erp.email.entity; import com.jadhavr.erp.common.entity.BaseAuditEntity;import com.jadhavr.erp.email.enums.*;import jakarta.persistence.*;import java.time.LocalDateTime;
@Entity @Table(name="email_notifications",indexes={@Index(name="idx_email_status_retry",columnList="status,next_retry_at"),@Index(name="idx_email_created",columnList="created_at"),@Index(name="idx_email_type",columnList="email_type")},uniqueConstraints=@UniqueConstraint(name="uk_email_idempotency",columnNames="idempotency_key")) public class EmailNotification extends BaseAuditEntity{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(nullable=false,length=150)private String recipientEmail;@Column(length=150)private String recipientName;@Enumerated(EnumType.STRING)@Column(nullable=false,length=40)private EmailType emailType;@Column(nullable=false,length=200)private String subject;@Column(nullable=false,length=100)private String templateName;@Column(nullable=false,length=4000)private String templateData;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private EmailStatus status=EmailStatus.QUEUED;@Enumerated(EnumType.STRING)@Column(nullable=false,length=10)private EmailPriority priority=EmailPriority.NORMAL;private int retryCount;private int maxRetries;private LocalDateTime nextRetryAt;@Column(length=30)private String provider;@Column(length=200)private String providerMessageId;@Column(length=500)private String failureReason;private LocalDateTime sentAt;private LocalDateTime processingStartedAt;@Column(nullable=false,length=100)private String correlationId;@Column(nullable=false,length=250)private String idempotencyKey;
public Long getId(){return id;}public String getRecipientEmail(){return recipientEmail;}public void setRecipientEmail(String v){recipientEmail=v;}public String getRecipientName(){return recipientName;}public void setRecipientName(String v){recipientName=v;}public EmailType getEmailType(){return emailType;}public void setEmailType(EmailType v){emailType=v;}public String getSubject(){return subject;}public void setSubject(String v){subject=v;}public String getTemplateName(){return templateName;}public void setTemplateName(String v){templateName=v;}public String getTemplateData(){return templateData;}public void setTemplateData(String v){templateData=v;}public EmailStatus getStatus(){return status;}public void setStatus(EmailStatus v){status=v;}public EmailPriority getPriority(){return priority;}public void setPriority(EmailPriority v){priority=v;}public int getRetryCount(){return retryCount;}public void setRetryCount(int v){retryCount=v;}public int getMaxRetries(){return maxRetries;}public void setMaxRetries(int v){maxRetries=v;}public LocalDateTime getNextRetryAt(){return nextRetryAt;}public void setNextRetryAt(LocalDateTime v){nextRetryAt=v;}public String getProvider(){return provider;}public void setProvider(String v){provider=v;}public String getProviderMessageId(){return providerMessageId;}public void setProviderMessageId(String v){providerMessageId=v;}public String getFailureReason(){return failureReason;}public void setFailureReason(String v){failureReason=v;}public LocalDateTime getSentAt(){return sentAt;}public void setSentAt(LocalDateTime v){sentAt=v;}public LocalDateTime getProcessingStartedAt(){return processingStartedAt;}public void setProcessingStartedAt(LocalDateTime v){processingStartedAt=v;}public String getCorrelationId(){return correlationId;}public void setCorrelationId(String v){correlationId=v;}public String getIdempotencyKey(){return idempotencyKey;}public void setIdempotencyKey(String v){idempotencyKey=v;}}
